namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications = new();
    private int _nextId;

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            new Notification(++_nextId, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
            new Notification(++_nextId, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)),
            new Notification(++_nextId, "New feature available: dark mode.", DateTime.UtcNow.AddMinutes(-5)),
        });
    }

    /// <summary>Returns all notifications known so far.</summary>
    public Task<IReadOnlyList<Notification>> GetAllAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult<IReadOnlyList<Notification>>(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public Task<IReadOnlyList<Notification>> GetSinceAsync(int sinceId)
    {
        lock (_notifications)
        {
            return Task.FromResult<IReadOnlyList<Notification>>(
                _notifications.Where(n => n.Id > sinceId).ToList());
        }
    }

    /// <summary>
    /// Simulates an external system pushing a new notification.
    /// Called internally by a hosted service to generate fake traffic.
    /// </summary>
    public void Add(string message)
    {
        lock (_notifications)
        {
            _notifications.Add(new Notification(++_nextId, message, DateTime.UtcNow));
        }
    }
}

namespace NotificationsApp.Services;

/// <summary>
/// Background service that adds a new fake notification every ~8 seconds
/// so there is something for the polling loop to pick up.
/// </summary>
public class FakeNotificationProducer : BackgroundService
{
    private static readonly string[] Messages =
    [
        "Deployment to production succeeded.",
        "CPU usage exceeded 90% on server-3.",
        "User 'alice' signed up.",
        "Scheduled backup completed.",
        "New comment on issue #42.",
        "Disk space warning on server-1.",
        "Password policy was updated.",
    ];

    private readonly NotificationService _service;

    public FakeNotificationProducer(NotificationService service) => _service = service;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var rng = new Random();
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            _service.Add(Messages[rng.Next(Messages.Length)]);
        }
    }
}

